from playwright.sync_api import sync_playwright
F=[('oval','Oval','428f6af5a765|bcdc589a95be','Quase qualquer formato'),('redondo','Redondo','9ab7b593fca6|27767c040646','Retangulares ou angulares'),('quadrado','Quadrado','b57df54a8c85|283ae4caf0a7','Arredondadas ou ovais'),('alongado','Alongado','3ce001776234|1cd5b45bfb7a','Grandes e largas'),('coracao','Coração','93e9e7f328ca|f1e6a9689a21','Aviador ou leves'),('diamante','Diamante','21bdac22d73f|26554b09a3e5','Gatinho ou ovais')]
CAM='<svg viewBox="0 0 24 24" width="SZ" height="SZ" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 8h3l1.6-2.4h6.8L17 8h3a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1z"/><circle cx="12" cy="13.2" r="3.6"/></svg>'
FACE='<svg viewBox="0 0 200 220" width="SZ" fill="none" stroke="#1d1d1f" stroke-linecap="round" stroke-linejoin="round"><g stroke-width="5"><path d="M30 20h-14v14M170 20h14v14M30 200h-14v-14M170 200h14v-14"/></g><g stroke-width="4"><path d="M100 36c-38 0-58 30-58 70 0 46 26 84 58 84s58-38 58-84c0-40-20-70-58-70z"/><path d="M74 104q10-6 20 0M106 104q10-6 20 0"/><path d="M100 112v22q-4 4 0 6"/><path d="M84 158q16 10 32 0"/></g><g stroke="#8d3a69" stroke-width="2.5" stroke-dasharray="5 6"><circle cx="42" cy="106" r="5" fill="#8d3a69"/><circle cx="158" cy="106" r="5" fill="#8d3a69"/><circle cx="100" cy="36" r="5" fill="#8d3a69"/><circle cx="100" cy="190" r="5" fill="#8d3a69"/><path d="M42 106H158M100 36V190"/></g></svg>'
def img1(h,w='100%',hh='100%'): return f'<span style="display:block;width:{w};height:{hh};background:#1d1d1f;-webkit-mask:url(/media/i/{h}.png) center/contain no-repeat;mask:url(/media/i/{h}.png) center/contain no-repeat"></span>'
def img(h):
    a,b=h.split('|');return '<span style="display:flex;gap:2px;height:100%">'+img1(a,'50%')+img1(b,'50%')+'</span>'
CSS='''<style>#rosto.zz{padding:0 16px 40px!important;text-align:left!important}#rosto.zz *{box-sizing:border-box}
.zb{display:flex;align-items:center;gap:6px;color:#8d3a69;font:600 15px Inter,system-ui,sans-serif;margin:14px 0 4px}
.zt{font:600 26px Fraunces,Georgia,serif;color:#2a1f27;margin:0}
.zs{text-align:left!important;max-width:none!important;font:400 15px Inter,system-ui,sans-serif;color:#6b5f68;margin:6px 0 18px;line-height:1.45}
.ze{font:800 12px Inter,system-ui,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:#8d3a69;margin:26px 0 10px}
.zh{display:flex;justify-content:space-between;align-items:baseline;margin:26px 0 12px}.zh b{font:600 22px Fraunces,Georgia,serif;color:#2a1f27}.zh a{color:#8d3a69;font:600 15px Inter,sans-serif}
.zc{background:#fff;border:1px solid #eadfe7;border-radius:22px}
.zbt{display:flex;align-items:center;justify-content:center;gap:10px;border-radius:999px;padding:14px 18px;font:700 16px Inter,sans-serif;color:#fff;background:linear-gradient(90deg,#7a2a5f,#d68cb7);border:0;width:100%}
.zg{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.zf{padding:12px 10px 14px;text-align:center}.zf b{display:block;font:600 17px Fraunces,Georgia,serif;color:#2a1f27;margin-top:8px}.zf small{display:block;font:400 12.5px Inter,sans-serif;color:#7a6d77;margin-top:3px;line-height:1.3}
.zpi{background:#faf5f8;border-radius:14px;height:104px;padding:8px}
.zchip{flex:none;border:1.5px solid #eadfe7;border-radius:999px;padding:8px 14px;font:600 14px Inter,sans-serif;color:#2a1f27;background:#fff}.zchip.on{border-color:#2a1f27}
.zrow{display:flex;align-items:center;gap:14px;padding:12px 14px;border-bottom:1px solid #f1e8ee}.zrow:last-child{border:0}.zrow b{font:600 17px Fraunces,Georgia,serif;color:#2a1f27}.zrow small{display:block;font:400 13px Inter,sans-serif;color:#7a6d77;margin-top:2px}
.zok{font:500 13px Inter,sans-serif;color:#6b5f68;display:flex;gap:14px;justify-content:center;margin-top:10px}</style>'''
HEAD='<div class="zb"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><path d="M15 5l-7 7 7 7"/></svg>Início</div><h1 class="zt">Seu formato de rosto</h1><p class="zs">Veja quais armações valorizam o seu rosto.</p>'
camHero=lambda: '<div class="zc" style="padding:16px;display:flex;gap:14px;align-items:center;background:linear-gradient(160deg,#fff,#f8eef4)"><div style="flex:none;width:96px;height:104px;display:grid;place-items:center;background:#fff;border-radius:16px;border:1px solid #f0e4ec">'+FACE.replace('SZ','84')+'</div><div style="flex:1"><div style="font:800 11px Inter,sans-serif;letter-spacing:.14em;color:#8d3a69">PELA CÂMERA · 1 MIN</div><div style="font:600 19px Fraunces,Georgia,serif;color:#2a1f27;margin:4px 0 10px;line-height:1.2">Descubra o seu formato</div><button class="zbt" style="padding:10px 14px;font-size:15px">'+CAM.replace('SZ','18')+'Abrir a câmera</button></div></div>'
A=CSS+HEAD+camHero()+'<div class="zh"><b>Ou escolha o seu</b></div><div class="zg">'+''.join(f'<div class="zc zf"><div class="zpi">{img(h)}</div><b>{n}</b><small>{d}</small></div>' for k,n,h,d in F)+'</div>'
B=CSS+HEAD+'<div style="display:flex;gap:8px;overflow:hidden;margin:0 -16px 14px;padding:0 16px"><span class="zchip on">'+CAM.replace('SZ','15')+' Câmera</span>'+''.join(f'<span class="zchip">{n}</span>' for k,n,h,d in F[:4])+'</div>'+ \
  '<div style="display:flex;gap:12px;overflow:hidden;margin:0 -16px;padding:0 16px"><div class="zc" style="flex:none;width:78%;padding:14px;text-align:center;border-color:#8d3a69"><div class="zpi" style="height:220px;display:grid;place-items:center;background:#faf5f8">'+FACE.replace('SZ','170')+'</div><b style="display:block;font:600 22px Fraunces,Georgia,serif;color:#8d3a69;margin:12px 0 4px">Não sei o meu</b><small style="display:block;font:400 14px Inter,sans-serif;color:#6b5f68;line-height:1.4;margin-bottom:14px">A câmera mede o seu rosto e mostra os modelos que combinam.</small><button class="zbt">'+CAM.replace('SZ','20')+'Abrir a câmera</button></div><div class="zc" style="flex:none;width:78%;padding:14px;opacity:.6"><div class="zpi" style="height:220px">'+img(F[0][2])+'</div></div></div>'+ \
  '<div class="zok"><span>● 1 min</span><span>● Grátis</span><span>● Sem cadastro</span></div>'+ \
  '<div class="zh"><b>Como funciona</b></div><div class="zc">'+''.join(f'<div class="zrow"><span style="width:30px;height:30px;border-radius:50%;background:#f3e1ec;color:#8d3a69;display:grid;place-items:center;font:700 14px Inter">{i}</span><span style="font:400 15px Inter,sans-serif">{t}</span></div>' for i,t in [(1,'Abra a câmera e olhe de frente'),(2,'Medimos o formato do seu rosto'),(3,'Mostramos os modelos que combinam')])+'</div>'
C=CSS+HEAD+camHero()+'<div class="zh"><b>Escolha o seu formato</b></div><div class="zc">'+''.join(f'<div class="zrow"><span style="flex:none;width:64px;height:58px;background:#faf5f8;border-radius:12px;padding:5px">{img(h)}</span><span style="flex:1"><b>{n}</b><small>Combina: {d.lower()}</small></span><span style="color:#8d3a69;font-size:22px">›</span></div>' for k,n,h,d in F)+'</div>'
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/opt/pw-browsers/chromium',args=['--no-sandbox'])
    for tag,html in (('A',A),('B',B),('C',C)):
        pg=b.new_page(viewport={'width':390,'height':1300},device_scale_factor=2,is_mobile=True,has_touch=True,locale='pt-BR')
        pg.goto('http://localhost:8766/'); pg.wait_for_timeout(2500)
        pg.evaluate("document.querySelector('a[href=\"#rosto\"]').click()"); pg.wait_for_timeout(1500)
        pg.evaluate("h=>{var r=document.querySelector('#rosto');r.classList.add('zz');r.innerHTML=h;r.scrollTop=0}",html); pg.wait_for_timeout(1200)
        pg.screenshot(path=f'pg_{tag}.png'); pg.close()
